#ifndef MENU_H
#define MENU_H

#define MENU_MAX_TOKENS   (8)    /* tokens per command line and per syntax */
#define MENU_MAX_ARGS     (4)    /* captured parameters per command */
#define MENU_LINE_MAX     (96)   /* longest accepted line, including the terminating NUL */
#define MENU_EXIT         (1)     /* Menu_ProcessLine return: the user typed EXIT */

/** Parameters captured for one callback; argv points into the caller-lifetime line copy. */
typedef struct
{
    int         argc;
    const char *argv[MENU_MAX_ARGS];
} MenuCommandContext;

/** Command callback: returns 0 on success, negative on failure. */
typedef int (*MenuCallback)(const MenuCommandContext *ctx);

/** Output sink supplied by the platform (UART ring on the target, stdout on the host). */
void menu_write(const char *text);

void Menu_Init(void);
int  Menu_ProcessLine(const char *line);
void Menu_PrintHelp(void);
int  Menu_ParseU32(const char *text, unsigned long *value);

/* Callbacks (implemented by the application; one per cli_commands.txt line). */
int cli_version(const MenuCommandContext *ctx);
int cli_ddr_info(const MenuCommandContext *ctx);
int cli_sid_status(const MenuCommandContext *ctx);
int cli_audio_status(const MenuCommandContext *ctx);
int cli_codec_read(const MenuCommandContext *ctx);
int cli_codec_write(const MenuCommandContext *ctx);
int cli_drive_status(const MenuCommandContext *ctx);
int cli_drive_cmd(const MenuCommandContext *ctx);
int cli_video_status(const MenuCommandContext *ctx);
int cli_video_palette(const MenuCommandContext *ctx);
int cli_keyboard_stats(const MenuCommandContext *ctx);

#endif /* MENU_H */
